CREATE OR REPLACE VIEW kfl_production_dbp_view.v_l_angebot_attribut_2 (mandant_id OPTIONS(description='Mandant_2 im DWH'),
angebot_attribut_id OPTIONS(description='ID des Attributs.'))
OPTIONS(DESCRIPTION = `ENTHÄLT MÖGLICHE ATTRIBUTE / CHARAKTERISTIKEN DIE EINEM ANGEBOT_2 ZUSÄTZLICH NOCH HINZUGEFÜGT WERDEN KÖNNEN. DIESE ZUSÄTZLICHEN ATTRIBUTE KÖNNEN DABEI SEHR UNTERSCHEIDLICH SEIN UND BEISPIELSWEISE INFORMATIONEN ZU DEN BESTELLMENGEN, PLATZIERUNG IN DER FILIALE, DARSTELLUNG IM WERBEMITTEL, ETC. ENTHALTEN.`)
AS SELECT mandant_id,
 angebot_attribut_id
FROM kfl_production_dbp_data.l_angebot_attribut_2;